ion","lettre":"A","correct":true},{"texte":"Le bâtiment","lettre":"B","correct":true},{"texte":"La production","lettre":"C","correct":true},{"texte":"Les services","lettre":"D","correct":true},{"texte":"Le transport","lettre":"E"}],"type":"QCM","image":null},{"id":197,"enonce":"Quel est le capital maximum pour créer une SARL ?","choix":[{"texte":"1€","lettre":"A"},{"texte":"100€","lettre":"B"},{"texte":"1000€","lettre":"C"},{"texte":"Pas de montant maximum","lettre":"D","correct":true}],"type":"QCM","image":null},{"id":198,"enonce":"Une entreprise individuelle :","choix":[{"texte":"doit changer de statut juridique pour embaucher un salarié","lettre":"A","correct":false},{"texte":"peut embaucher des salariés","lettre":"B","correct":true},{"texte":"ne peut embaucher qu''un apprenti","lettre":"C"}],"type":"QCM","image":null,"imageSize":"sm"},{"id":199,"enonce":"Le Président de la Chambre de Métiers et de l''Artisanat est :","choix":[{"texte":"un(e) salarié(e) de la fonction publique","lettre":"A","correct":false},{"texte":"un(e) artisan(e) en exercice","lettre":"B","correct":true},{"texte":"une personne nommée par le Préfet de région","lettre":"C"}],"type":"QCM","image":null,"imageSize":"sm"},{"id":206,"enonce":"LE CHIFFRE D''AFFAIRES D''UN ARTISAN T3P PASSE DE 10 100 € À 15 440 €, L''ANNÉE SUIVANTE. QUEL EST LE POURCENTAGE D''AUGMENTATION ?","choix":[{"texte":"54.20 %","lettre":"A"},{"texte":"52.87 %","lettre":"B","correct":true},{"texte":"51.83 %","lettre":"C"}],"type":"QCM","image":null}]'::jsonb AS q) z RETURNING id, subject)
