":"A"},{"texte":"2 secondes","lettre":"B","correct":true},{"texte":"3 secondes","lettre":"C"}],"type":"QCM","image":null,"imageSize":"sm"},{"id":70,"enonce":"En présence de deux marquages, un jaune et un blanc, je respecte en priorité :","choix":[{"texte":"Le marquage blanc","lettre":"A"},{"texte":"Le marquage jaune","lettre":"B","correct":true}],"type":"QCM","image":null,"imageSize":"sm"},{"id":71,"enonce":"Sur une route étroite, un camion arrive en face. Dois-je lui céder le passage ?","choix":[{"texte":"Oui","lettre":"A","correct":true},{"texte":"Non","lettre":"B"}],"type":"QCM","image":null,"imageSize":"sm"},{"id":72,"enonce":"Dernier d''une file qui ralentit fortement, je dois allumer mes feux de détresse :","choix":[{"texte":"Vrai","lettre":"A","correct":true},{"texte":"Faux","lettre":"B"}],"type":"QCM","image":null,"imageSize":"sm"},{"id":73,"enonce":"Le stationnement et l''arrêt sont interdits sur la Bande d''arrêt d''urgence (hors panne) :","choix":[{"texte":"Vrai","lettre":"A","correct":true},{"texte":"Faux","lettre":"B"}],"type":"QCM","image":null,"imageSize":"sm"},{"id":74,"enonce":"Les feux de positions arrière doivent être visibles à :","choix":[{"texte":"100 m","lettre":"A"},{"texte":"150 m","lettre":"B","correct":true}],"type":"QCM","image":null,"imageSize":"sm"},{"id":75,"enonce":"Le chargement d''un véhicule peut dépasser à l''arrière de :","choix":[{"texte":"2 m","lettre":"A","correct":true},{"texte":"3 m","lettre":"B","correct":false}],"type":"QCM","image":null,"imageSize":"sm"},{"id":76,"enonce":"Présente sur les routes étroites, cette ligne autorise le dépassement :","choix":[{"texte":"De tous les véhicules","lettre":"A"},{"texte":"Seulement des véhicules roulant doucement","lettre":"B","correct":true}],"type":"QCM","image":null,"imageSize":"sm"},{"id":77,"enonce":"Dans une rue à sens unique, une voie de bus peut être à contresens :","choix":[{"texte":"Oui","lettre":"A","correct":true},{"texte":"Non","lettre":"B"}],"type":"QCM","image":null,"im